// ACME LINKEDIN DAILY — CONFIG
// Edit values only in this node. Nothing else in either workflow needs changing.
// Both workflows carry an identical copy of this node; change one, change the other.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what
// lets the whole pipeline be demonstrated on a screen-share before a single credential
// exists — see LOOM.md.

// ---------------------------------------------------------------- The content sheet
// The id is the long code in the sheet's web address:
// docs.google.com/spreadsheets/d/<THIS BIT>/edit
//
// Blank -> the DEMO_BANK posts below are used instead and nothing is logged. The draft is
// still written, rendered and delivered, so the pipeline can be watched end to end with no
// Google account attached at all.
const SHEET_ID = '';
const BANK_TAB = 'Bank';   // one row per post, in publish order. sheet/Bank.csv
const LOG_TAB  = 'Log';    // append-only outcome log. sheet/Log.csv

// Column headings, exactly as they appear in row 1 of each tab.
const BANK_COLUMNS = {
  slot:          'Slot',
  slug:          'Slug',
  pillar:        'Pillar',
  category:      'Category',
  headline:      'Headline',
  headline_size: 'Headline size',
  subhead:       'Subhead',
  layout:        'Layout',
  items:         'Items',        // JSON array — shape depends on Layout
  band:          'Band',         // grid only
  stat_big:      'Stat big',     // stat only
  stat_sub:      'Stat sub',     // stat only
  footer:        'Footer',
  caption:       'Caption',      // blank -> written by the model, if one is configured
  state:         'State'         // ready | posted | cancelled | holding
};

const LOG_COLUMNS = {
  date:       'Date',
  slug:       'Slug',
  slot:       'Slot',
  status:     'Status',       // awaiting | posted | cancelled | expired | skipped | failed
  channel_id: 'Channel id',
  message_id: 'Message id',   // the Discord draft — how workflow 02 finds the reply
  caption_fp: 'Caption fp',   // fingerprint of the delivered caption
  urn:        'Post urn',
  note:       'Note',
  at:         'At'
};

// Only these bank states are drafted. Anything else is treated as already handled.
const READY_STATES = ['', 'ready'];

// ---------------------------------------------------------------- When it runs
// The schedule lives on the trigger node, not here — this is the guard that stops a manual
// run at 11pm on a Sunday from putting a post out on a day it should not.
// 1 = Monday ... 7 = Sunday.
const PUBLISH_DAYS = [1, 2, 3, 4, 5];
const TIMEZONE     = 'Asia/Singapore';

// Design-side posts go out on Thursdays. build.js in the drafts repo enforces this at build
// time; this is the same rule enforced again at publish time, because the bank can be
// reordered in the sheet long after it was built.
const DESIGN_PILLAR_PREFIX     = 'Design process';
const ENFORCE_DESIGN_THURSDAY  = true;
const OFF_CADENCE_DESIGN_SLOTS = [6];   // slot 6 is a Friday, and went out that way on purpose

// No two posts published within this many slots may share a layout or a pillar. Five is a
// publishing week at the weekday cadence. Measured in slots, not dates.
const WINDOW_SLOTS = 5;

// ---------------------------------------------------------------- Brand system
// DESIGN.md is the source of record for all of this. Changing a colour here changes every
// future render; it does not reflow anything already published.
const BRAND = {
  bg:          '#050505',
  accent:      '#DC2056',
  white:       '#FFFFFF',
  muted:       '#A8A8A8',
  line:        '#303030',
  card_border: '#262626',
  card_bg:     '#0B0B0B',
  font:        'Arial, Helvetica, sans-serif',
  site:        'acme.example'
};

const CANVAS_WIDTH  = 1080;
const CANVAS_HEIGHT = 1350;
const DEVICE_SCALE  = 2;      // 2 -> a 2160x2700 PNG from a 1080x1350 canvas

// The wordmark, inlined into the template. The renderer loads the HTML with no network, so
// nothing here may reference a file or a URL. Paste the contents of acme_logo_12.svg
// (white wordmark, pink mark) between the quotes. Left blank the template falls back to a
// plain text wordmark, which is visibly not the logo — on purpose. A missing logo must look
// missing rather than quietly pass review.
const LOGO_SVG = '';

// ---------------------------------------------------------------- The renderer
// HTML -> PNG. n8n has no browser of its own, so this is one HTTP call out.
//
//   'browserless' — self-hosted, and the one to use. Add it to the same docker-compose file
//                   n8n runs in and point RENDER_URL at http://browserless:3000. Returns
//                   the PNG bytes directly.
//   'hcti'        — htmlcsstoimage.com. RENDER_USER / RENDER_KEY are the API id and key.
//                   Returns a JSON url, which the workflow then downloads.
//   ''            -> no image. The run stops at "STOP: renderer not configured" and delivers
//                    nothing, because a caption without its image is not a draft.
const RENDER_PROVIDER = 'browserless';
const RENDER_URL      = 'http://browserless:3000';
const RENDER_USER     = '';   // hcti only
const RENDER_KEY      = '';   // browserless token, or the hcti api key

// A render that comes back under this many bytes is a blank or half-drawn canvas, not a
// post. Measured against the live bank: the smallest real render is about 87 KB.
const MIN_PNG_BYTES = 40000;

// ---------------------------------------------------------------- Discord approval
// The channel the draft is delivered to, and the only place an approval is read from.
//
// ANYONE WHO CAN SEND A MESSAGE IN THIS CHANNEL CAN PUBLISH TO THE COMPANY PAGE. Use a
// private channel created for this and nothing else — not a general channel, where one
// person typing a common English word publishes a draft.
//
// The bot token goes in an n8n Discord credential, not here.
const DISCORD_CHANNEL_ID = '';

// What a reviewer types. Matched case-insensitively against the whole message, trimmed.
// Trailing text is NOT tolerated: "post" approves, "post please" does not, because the
// looser the match the more ways an unrelated sentence becomes a publish.
const APPROVE_WORDS = ['post', 'approve', 'ship it'];
const CANCEL_WORDS  = ['cancel', 'reject', 'discard'];

// How long a draft stays approvable. After this the day has moved on and the claims in it
// may not have. Workflow 02 marks it expired rather than publishing it.
const APPROVAL_EXPIRES_HOURS = 20;

// ---------------------------------------------------------------- LinkedIn
// The organisation to post as, and the token that may post as it.
// urn:li:organization:<id> — the id is in the page's admin URL.
const LINKEDIN_ORG_URN = 'urn:li:organization:96592857';

// A w_organization_social token. Blank -> nothing is ever published, whatever a reviewer
// replies; the run reaches "STOP: not published" and says why.
const LINKEDIN_ACCESS_TOKEN = '';

// Probed 2026-08-18: 202512 and earlier are retired (HTTP 426 NONEXISTENT_VERSION).
// 202601..202608 are active.
const LINKEDIN_VERSION = '202608';

// ---------------------------------------------------------------- Writing the caption
// Only used for a bank row whose Caption cell is empty. A row that already carries a caption
// is delivered as written — the model never rewrites approved copy.
//
// Blank key -> a row with no caption is held back with a reason, never delivered bare.
const LLM_BASE_URL = 'https://llm.acme.example';
const LLM_API_KEY  = '';
const LLM_MODEL    = 'modelark/seed-2-0-pro-260328';

// The caption rules, from the acme-linkedin-content skill. These are handed to the model
// and are also checked in code afterwards, because a model asked for 220 words will
// sometimes write 340 and say it wrote 220.
const CAPTION_MIN_WORDS = 120;
const CAPTION_MAX_WORDS = 220;
const HASHTAGS_MIN      = 4;
const HASHTAGS_MAX      = 6;
const MAX_EMOJI         = 1;

// Rejected outright, in a written caption or a banked one. A caption that trips this is held
// back with the phrase named, never quietly edited.
const BANNED_PHRASES = [
  'game changer', 'game-changer', 'revolutionary', 'the future is here',
  'cutting edge', 'cutting-edge', 'unlock the power', 'next level',
  'fast-paced world', 'seamlessly', 'synergy', 'paradigm shift',
  'thought leader', 'disrupt', 'skyrocket', 'supercharge',
  'best-in-class', 'world-class', 'leverage our'
];

// Discord's hard limit on one message is 2000 characters. The caption travels in the message
// body so the reviewer reads exactly what would be published.
const DISCORD_MESSAGE_LIMIT = 2000;

// ---------------------------------------------------------------- Optional notification
const REPORT_WEBHOOK_URL = '';   // Slack incoming webhook. Blank = no notification.

// ---------------------------------------------------------------- Demo bank
// Used only when SHEET_ID is blank. Three posts, three layouts, so a screen-share shows the
// renderer doing real work before any Google account is attached. While the demo bank is in
// use the run is FORCED into preview: made-up content can never reach the company page.
const DEMO_BANK = [
  {
    slot: 1, slug: 'demo-map-the-failure-mode', pillar: 'Engineering insight',
    category: 'RESILIENCE',
    headline: 'ONE OUTAGE.<br>HOW MANY<br><em>BLOCKED TEAMS</em>?',
    headline_size: 94,
    subhead: 'A dependency you never wrote down is still a dependency.',
    layout: 'timeline',
    items: [
      ['Ship a hotfix', 'Without the pipeline, what is your deploy path?'],
      ['Authenticate', 'If SSO is down, who can still get in?'],
      ['Build artifacts', 'Do they exist anywhere other than there?'],
      ['Your assistant', 'Work stopped, or just slower?']
    ],
    footer: 'Map the failure mode first.',
    caption: 'DEMO DRAFT — not for publication.\n\nThis is what the pipeline delivers '
      + 'for review every morning: a caption, and the image it would go out with.\n\nThe '
      + 'layout, the palette and the one-accent rule come from the design system, applied '
      + 'in code rather than retyped each time.\n\n#Demo #Acme'
  },
  {
    slot: 2, slug: 'demo-never-approve-your-own-work',
    pillar: 'Production AI guardrails', category: 'AI GUARDRAILS',
    headline: 'NEVER APPROVE<br><em>YOUR OWN WORK</em>.',
    headline_size: 90,
    subhead: 'Four things a workflow must never read as a human saying yes.',
    layout: 'grid',
    items: [
      ['Its own message', 'The draft it just posted for review'],
      ['Another bot', 'A second agent is not a second opinion'],
      ['Silence', 'Nobody objected is not anybody approved'],
      ['A reaction', 'A thumbs-up is not a signature']
    ],
    band: 'APPROVAL IS A HUMAN, IN THE RIGHT CHANNEL.',
    footer: 'Everything else is the system agreeing with itself.',
    caption: 'DEMO DRAFT — not for publication.\n\nThe approval gate in this pipeline '
      + 'reads one channel and ignores its own messages. That is the whole guardrail.\n\n'
      + '#Demo #Acme'
  },
  {
    slot: 3, slug: 'demo-reporting-costs-a-day', pillar: 'AI workflow, reporting',
    category: 'REPORTING',
    headline: 'IT ISN’T ANALYSIS.<br>IT’S <em>COLLECTION</em>.',
    headline_size: 92,
    subhead: 'A day of assembling. Four minutes of reading.',
    layout: 'cards',
    items: [
      ['STEP 01 · COLLECT', 'Numbers<br>assemble', 'Exports and systems pulled on a schedule.'],
      ['STEP 02 · RECONCILE', 'Conflicts<br>surface', 'Sources that disagree get flagged, never averaged.'],
      ['STEP 03 · DECIDE', 'Stays<br>human', 'Someone still decides which system is right.']
    ],
    footer: 'The judgement stays. The copying goes.',
    caption: 'DEMO DRAFT — not for publication.\n\nThird layout, same build node. The '
      + 'bank row picks the layout; nothing downstream changes.\n\n#Demo #Acme'
  }
];

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_CHANNEL_ID blank -> PREVIEW. The draft is written and rendered so
//                                            you can look at the PNG, but it is delivered
//                                            nowhere and published nowhere. Ships this way.
//   TEST_RUN true,  TEST_CHANNEL_ID set   -> TEST. The draft really is delivered, to that
//                                            channel instead of the live one, and approvals
//                                            are read there. LinkedIn is still never
//                                            published to.
//   TEST_RUN false                        -> LIVE. Delivered to DISCORD_CHANNEL_ID, and an
//                                            approval there publishes to the company page.
//
// Filling in TEST_CHANNEL_ID can only ever redirect a delivery. It cannot cause a publish —
// going live is the separate, deliberate act of setting TEST_RUN = false.
const TEST_RUN        = true;
const TEST_CHANNEL_ID = '';

// Hard ceiling on posts published per run. One a day is the whole design; this exists so a
// bad batch of rows cannot become a bad batch of posts.
const DAILY_CAP = 1;

// ---------------------------------------------------------------- derived
const USING_DEMO_BANK = SHEET_ID.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_CHANNEL_ID.trim() !== '' ? 'test' : 'preview');

// Demo content is not a post. It cannot open the publish gate, whatever TEST_RUN says.
const FORCED_PREVIEW = USING_DEMO_BANK && MODE === 'live';
if (FORCED_PREVIEW) MODE = 'preview';

const CHANNEL_ID = MODE === 'test' ? TEST_CHANNEL_ID.trim() : DISCORD_CHANNEL_ID.trim();

const lower = (a) => a.map((s) => String(s).trim().toLowerCase()).filter(Boolean);

return [{
  json: {
    sheet_id: SHEET_ID.trim(),
    bank_tab: BANK_TAB,
    log_tab:  LOG_TAB,
    bank_columns: BANK_COLUMNS,
    log_columns:  LOG_COLUMNS,
    ready_states: READY_STATES.map((s) => String(s).trim().toLowerCase()),

    publish_days: PUBLISH_DAYS.map(Number),
    timezone:     TIMEZONE,

    design_pillar_prefix:     DESIGN_PILLAR_PREFIX,
    enforce_design_thursday:  ENFORCE_DESIGN_THURSDAY !== false,
    off_cadence_design_slots: OFF_CADENCE_DESIGN_SLOTS.map(Number),
    window_slots:             Number(WINDOW_SLOTS) || 5,

    brand:         BRAND,
    canvas_width:  Number(CANVAS_WIDTH) || 1080,
    canvas_height: Number(CANVAS_HEIGHT) || 1350,
    device_scale:  Number(DEVICE_SCALE) || 1,
    logo_svg:      LOGO_SVG,

    render_provider: RENDER_PROVIDER.trim().toLowerCase(),
    render_url:      RENDER_URL.replace(/\/+$/, ''),
    render_user:     RENDER_USER.trim(),
    render_key:      RENDER_KEY.trim(),
    min_png_bytes:   Number(MIN_PNG_BYTES) || 0,

    channel_id:     CHANNEL_ID,
    approve_words:  lower(APPROVE_WORDS),
    cancel_words:   lower(CANCEL_WORDS),
    approval_expires_hours: Number(APPROVAL_EXPIRES_HOURS) || 20,
    discord_message_limit:  Number(DISCORD_MESSAGE_LIMIT) || 2000,

    linkedin_org_urn: LINKEDIN_ORG_URN.trim(),
    linkedin_token:   LINKEDIN_ACCESS_TOKEN.trim(),
    linkedin_version: LINKEDIN_VERSION,

    llm_base_url: LLM_BASE_URL.replace(/\/+$/, ''),
    llm_api_key:  LLM_API_KEY.trim(),
    llm_model:    LLM_MODEL,

    caption_min_words: Number(CAPTION_MIN_WORDS) || 0,
    caption_max_words: Number(CAPTION_MAX_WORDS) || 400,
    hashtags_min:      Number(HASHTAGS_MIN) || 0,
    hashtags_max:      Number(HASHTAGS_MAX) || 6,
    max_emoji:         Number(MAX_EMOJI) || 0,
    banned_phrases:    lower(BANNED_PHRASES),

    report_webhook_url: REPORT_WEBHOOK_URL.trim(),
    demo_bank:          DEMO_BANK,
    daily_cap:          Number(DAILY_CAP) || 1,

    // derived flags — every gate reads these, never the raw constants
    mode:            MODE,
    preview_only:    MODE === 'preview',
    test_delivery:   MODE === 'test',
    live_publish:    MODE === 'live' && LINKEDIN_ACCESS_TOKEN.trim() !== '',
    sheet_enabled:   SHEET_ID.trim() !== '',
    using_demo_bank: USING_DEMO_BANK,
    forced_preview:  FORCED_PREVIEW,
    render_enabled:  RENDER_PROVIDER.trim() !== '' && RENDER_URL.trim() !== '',
    deliver_enabled: MODE !== 'preview' && CHANNEL_ID !== '',
    llm_enabled:     LLM_API_KEY.trim() !== '',
    report_enabled:  REPORT_WEBHOOK_URL.trim() !== '',
    logo_present:    LOGO_SVG.trim() !== ''
  }
}];

// Find the draft that is waiting on a human, if there is one.
//
// The log is the source of truth. Exactly one row may be `awaiting` at a time — workflow 01
// refuses to draft while one is open — so this either finds one or finds nothing.
//
// It also decides whether that draft is still approvable. A draft goes stale: the day moves
// on, the claims in it may not have, and an approval typed against yesterday's post at
// lunchtime today publishes something nobody re-read. After APPROVAL_EXPIRES_HOURS it is
// marked expired instead.
//
// Input: every row of the Log tab. Output: exactly one item, always.

const cfg = $('config').first().json;
const L = cfg.log_columns;

const norm = (v) => String(v === undefined || v === null ? '' : v).trim();

const rows = items.map((i) => i.json).filter((r) => r && (r[L.date] || r[L.slug]));

// Rows are appended, so the last `awaiting` is the current one. A log that somehow holds two
// is a real problem worth seeing rather than quietly picking one.
const awaiting = rows.filter((r) => norm(r[L.status]).toLowerCase() === 'awaiting');

if (!awaiting.length) {
  return [{
    json: {
      _has_pending: false,
      _reason: 'no draft is awaiting approval — ' + rows.length + ' log row(s), none open'
    }
  }];
}

if (awaiting.length > 1) {
  return [{
    json: {
      _has_pending: false,
      _conflict: true,
      _reason: awaiting.length + ' drafts are marked awaiting at once: '
        + awaiting.map((r) => norm(r[L.date]) + ' ' + norm(r[L.slug])).join(', ')
        + '. Workflow 01 only opens one at a time, so the log has been edited by hand or a '
        + 'run was interrupted mid-write. Resolve it in the sheet — do not publish either.'
    }
  }];
}

const row = awaiting[0];
const at = norm(row[L.at]);
const openedAt = at ? Date.parse(at) : NaN;
const ageHours = isNaN(openedAt) ? 0 : (Date.now() - openedAt) / 3600000;
const expired = !isNaN(openedAt) && ageHours > cfg.approval_expires_hours;

// The message the draft went out in is the anchor. Without it there is nothing to scan
// forward from, and a channel-wide search for the word "post" is exactly the ambiguity the
// dedicated-channel rule exists to prevent.
const messageId = norm(row[L.message_id]);
const channelId = norm(row[L.channel_id]) || cfg.channel_id;

return [{
  json: {
    _has_pending: !expired && messageId !== '',
    _expired: expired,
    _date: norm(row[L.date]),
    _slug: norm(row[L.slug]),
    _slot: Number(row[L.slot]) || 0,
    _message_id: messageId,
    _channel_id: channelId,
    _caption_fp: norm(row[L.caption_fp]),
    _age_hours: Math.round(ageHours * 10) / 10,
    _reason: expired
      ? 'the draft for ' + norm(row[L.slug]) + ' has been open ' + Math.round(ageHours)
        + ' hours, past the ' + cfg.approval_expires_hours + ' hour limit. Marked expired '
        + 'rather than published — re-run workflow 01 for a fresh one.'
      : messageId === ''
        ? 'the awaiting row for ' + norm(row[L.slug]) + ' has no message id, so there is no '
          + 'Discord message to read a reply from'
        : 'draft ' + norm(row[L.slug]) + ' has been awaiting approval for '
          + Math.round(ageHours * 10) / 10 + ' hours'
  }
}];

// Nothing is waiting on a human, so there is nothing to do.
//
// This is the normal state for most of the day: workflow 01 drafts once each morning and
// this workflow runs every few minutes, so the overwhelming majority of its executions end
// here. That is the design, not a fault — the alternative is a watcher process somebody has
// to keep alive across reboots.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'nothing awaiting',
    _mode: cfg.mode,
    _reason: '[IDLE] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// Read the channel and decide whether a human approved the draft.
//
// This is the gate. Everything downstream of it is irreversible, so the rules here are
// deliberately narrow and every one of them is a refusal:
//
//   * Only messages AFTER the draft count. Anything already in the channel when the draft
//     landed cannot be a reply to it.
//   * The workflow's own messages never count. The bot posted the draft, so any message from
//     that same author is the system agreeing with itself. This is checked against the
//     draft's own author id rather than a configured bot id — there is nothing to get wrong.
//   * Other bots never count. A second automation is not a second opinion.
//   * The whole message must be the word. "post" approves; "post please", "we should post
//     this" and "do not post" do not. Substring matching here would make "do not post"
//     an approval, which is the worst available bug.
//   * The FIRST decisive message wins. If someone says cancel and someone else says post a
//     minute later, the draft was already cancelled — a later approval does not reopen it.
//   * A cancel beats an approval in the same message. There is no such message, but if the
//     word lists are ever edited to overlap, the safe reading wins.
//
// Input: messages from the channel, newest-first as Discord returns them.
// Output: exactly one item, always, with _decision = post | cancel | wait.

const cfg = $('config').first().json;
const pending = $('find the pending draft').first().json;

const messages = items.map((i) => i.json).filter((m) => m && m.id);

// Discord snowflake ids sort chronologically as numbers, and they are wider than a JS
// integer — compare them as BigInt rather than as strings, because string comparison puts
// a 19-digit id before a 20-digit one.
const anchor = BigInt(pending._message_id);
const draft = messages.find((m) => m.id === pending._message_id);

// The author of the draft is the identity that must never be trusted as an approver. If the
// draft message is no longer in the fetched window we cannot establish that identity, and
// the safe answer is to wait rather than to guess.
if (!draft) {
  return [{
    json: Object.assign({}, pending, {
      _decision: 'wait',
      _reason: 'the draft message ' + pending._message_id + ' was not in the messages read '
        + 'back from the channel. It may have scrolled out of the fetch window or been '
        + 'deleted. Nothing is published on an unverifiable draft.'
    })
  }];
}

const botAuthorId = String((draft.author && draft.author.id) || '');

const after = messages
  .filter((m) => {
    try { return BigInt(m.id) > anchor; } catch (e) { return false; }
  })
  .sort((a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : 1));   // oldest first

let decision = 'wait';
let approver = '';
let approverId = '';
let said = '';
const ignored = [];

for (const m of after) {
  const authorId = String((m.author && m.author.id) || '');
  const isBot = Boolean(m.author && m.author.bot);
  const content = String(m.content || '').trim().toLowerCase();

  if (!content) continue;

  if (authorId === botAuthorId) {
    ignored.push('own message: "' + content.slice(0, 40) + '"');
    continue;
  }
  if (isBot) {
    ignored.push('another bot (' + ((m.author && m.author.username) || authorId) + '): "'
      + content.slice(0, 40) + '"');
    continue;
  }

  const isCancel = cfg.cancel_words.includes(content);
  const isApprove = cfg.approve_words.includes(content);

  if (isCancel) { decision = 'cancel'; }
  else if (isApprove) { decision = 'post'; }
  else { ignored.push('not a decision: "' + content.slice(0, 40) + '"'); continue; }

  approver = (m.author && (m.author.global_name || m.author.username)) || authorId;
  approverId = authorId;
  said = content;
  break;   // first decisive message wins
}

return [{
  json: Object.assign({}, pending, {
    _decision: decision,
    _approver: approver,
    _approver_id: approverId,
    _said: said,
    _messages_after: after.length,
    _ignored: ignored,
    _reason: decision === 'post'
      ? approver + ' approved it ("' + said + '")'
      : decision === 'cancel'
        ? approver + ' cancelled it ("' + said + '")'
        : 'no decision yet — ' + after.length + ' message(s) since the draft, '
          + ignored.length + ' ignored'
  })
}];

// The row that closes the day.
//
// One row per outcome, appended — the log is never rewritten in place. `posted` is what
// silences tomorrow's duplicate check; `cancelled` is what lets workflow 01 draft again the
// same day; `expired` closes a draft nobody answered without claiming it went out.
//
// The bank row's State is updated separately, and only on a real publish. A cancelled post
// stays `ready` on purpose: cancelling means "not this one, now", not "never".

const cfg = $('config').first().json;
const L = cfg.log_columns;
const d = $json;

const status = d._outcome === 'POSTED' ? 'posted'
  : d._decision === 'cancel' ? 'cancelled'
  : d._expired ? 'expired'
  : d._outcome === 'DUPLICATE' ? 'posted'
  : 'failed';

const row = {};
row[L.date] = d._date || '';
row[L.slug] = d._slug || '';
row[L.slot] = d._slot || '';
row[L.status] = status;
row[L.channel_id] = d._channel_id || cfg.channel_id;
row[L.message_id] = d._message_id || '';
row[L.caption_fp] = d._caption_fp_now || d._caption_fp || '';
row[L.urn] = d._urn || '';
row[L.note] = [
  d._approver ? 'by ' + d._approver : '',
  d._said ? '"' + d._said + '"' : '',
  d._reason || ''
].filter(Boolean).join(' — ').slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: Object.assign(row, { _status: status, _reason: d._reason }) }];

// The draft is still open. Nobody has replied yet.
//
// Deliberately does nothing else — no reminder, no nudge, no escalation. A reviewer who has
// not answered has not answered; pinging them from a workflow that publishes on the word
// "post" trains people to type it quickly.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'still awaiting approval',
    _mode: cfg.mode,
    _reason: '[WAITING] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// Reconstruct exactly what was approved — and refuse if it is not what was delivered.
//
// The caption published is taken from the DISCORD MESSAGE, not from the bank. That is
// deliberate: the message is what the human read, and the bank row could have been edited in
// the spreadsheet in the hours since. Publishing the bank row would publish something nobody
// approved.
//
// The fingerprint written at draft time then proves the message itself has not been edited.
// Discord lets an author edit a message in place, and an edited draft carries an approval
// that was given for different words. A mismatch stops the run rather than publishing
// either version.
//
// The image is the attachment on that same message: the picture the reviewer actually saw,
// fetched fresh so there is no expiring CDN link to keep.

const cfg = $('config').first().json;
const approval = $('read the approval reply').first().json;

const messages = items.map((i) => i.json).filter((m) => m && m.id);
const draft = messages.find((m) => m.id === approval._message_id);

const problems = [];

if (!draft) {
  return [{
    json: Object.assign({}, approval, {
      _publishable: false,
      _problems: ['the draft message disappeared between reading the approval and reading '
        + 'the draft'],
      _reason: 'the draft message is gone — nothing to publish'
    })
  }];
}

// Strip the approval instruction back off. It was appended by "build the approval message"
// and is the only thing in the message that is not the caption.
const INSTRUCTION = 'Reply **post** to publish, or **cancel** to discard.';
let caption = String(draft.content || '');
if (caption.endsWith(INSTRUCTION)) {
  caption = caption.slice(0, -INSTRUCTION.length);
} else {
  problems.push('the draft message does not end with the approval line, so it is not the '
    + 'message this workflow delivered');
}
caption = caption.trim();

// Same FNV-1a as apply-the-caption.js. Both must change together if either does.
function fingerprint(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}

const fp = fingerprint(caption);
if (approval._caption_fp && fp !== approval._caption_fp) {
  problems.push('the caption in the channel no longer matches what was delivered '
    + '(logged ' + approval._caption_fp + ', now ' + fp + '). The message has been edited '
    + 'since it was approved. Cancel it and run workflow 01 again.');
}
if (draft.edited_timestamp) {
  problems.push('the draft message was edited at ' + draft.edited_timestamp);
}

const attachments = draft.attachments || [];
const image = attachments.find((a) =>
  String(a.content_type || '').startsWith('image/')
  || /\.png$/i.test(String(a.filename || '')));

if (!image) {
  problems.push('the draft message has no image attached. A caption is not a post — the '
    + 'approval was given for a picture that is no longer there.');
}

// LinkedIn "little text" escaping, applied at publish time. '#' is deliberately not escaped
// so hashtags keep working.
const RESERVED = '\\|{}@[]()<>*_~';
const escaped = caption.split('').map((c) => (RESERVED.includes(c) ? '\\' + c : c)).join('');

return [{
  json: Object.assign({}, approval, {
    _publishable: problems.length === 0,
    _caption: caption,
    _caption_escaped: escaped,
    _caption_fp_now: fp,
    _image_url: image ? image.url : '',
    _image_name: image ? image.filename : '',
    _image_bytes: image ? image.size : 0,
    _problems: problems,
    _reason: problems.length ? problems[0]
      : 'the approved draft is intact — ' + caption.length + ' characters, fingerprint '
        + fp + ', image ' + (image.size || 0) + ' bytes'
  })
}];

// What is in the channel is not what was approved.
//
// The message was edited, its image is gone, or the caption no longer matches the
// fingerprint written when it was delivered. An approval is given for specific words next
// to a specific picture; once either changes, the approval does not carry over.
//
// Nothing is published and nothing is repaired automatically. Cancel the draft and run
// workflow 01 again.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'the approved draft changed',
    _mode: cfg.mode,
    _reason: '[BLOCKED] ' + (s._problems || []).join('; '),
    _at: new Date().toISOString()
  })
}];

// Approved, but the publish gate is shut. Nothing was sent.
//
// Either TEST_RUN is still true, or LINKEDIN_ACCESS_TOKEN is blank. Both are the safe
// default and both are visible here rather than failing inside an HTTP node with a 401.
//
// The approval itself stays open, so setting the token and running again publishes the
// same approved draft. It does not have to be approved twice.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'not published',
    _mode: cfg.mode,
    _reason: cfg.mode !== 'live'
      ? '[BLOCKED] ' + s._approver + ' approved this, but the workflow is in ' + cfg.mode
        + ' mode. Set TEST_RUN = false in config to publish. The approval stays open.'
      : '[BLOCKED] ' + s._approver + ' approved this, but LINKEDIN_ACCESS_TOKEN is blank '
        + 'in config. The approval stays open.',
    _at: new Date().toISOString()
  })
}];

// Read what LinkedIn said, and decide whether anything is now on the page.
//
// This runs after the irreversible step. The one rule that matters: an UNKNOWN outcome is
// never retried. A publish that timed out may well have succeeded, and a retry puts the same
// post up twice — which cannot be undone from here and looks worse than a missing post.
//
// The three outcomes:
//
//   POSTED     a share URN came back. Log it, notify, done.
//   DUPLICATE  LinkedIn rejected it as already posted. Stop. Not an error to fix.
//   FAILED     a 4xx with a reason. Stop, read the reason, fix the cause. A 4xx does not
//              become a 2xx by being sent again.
//   UNKNOWN    no status, no urn, no error. Check the page by eye before doing anything.

const draft = $('the approved draft').first().json;

const res = $json || {};
const headers = res.headers || {};
const body = res.body !== undefined ? res.body : res;
const status = Number(res.statusCode || res.status || 0);

// The share URN comes back in a header, not the body. n8n lowercases header names on some
// versions and not others.
const urn = String(
  headers['x-restli-id'] || headers['X-RestLi-Id'] || headers['x-linkedin-id']
  || (body && body.id) || ''
);

let outcome;
let reason;

if (urn) {
  outcome = 'POSTED';
  reason = 'published as ' + urn;
} else if (status === 409 || /duplicate/i.test(JSON.stringify(body || ''))) {
  outcome = 'DUPLICATE';
  reason = 'LinkedIn rejected this as a duplicate — it is already on the page. Not retried.';
} else if (status >= 400) {
  const msg = (body && (body.message || body.error_description || body.error)) || '';
  outcome = 'FAILED';
  reason = 'HTTP ' + status + (msg ? ': ' + JSON.stringify(msg) : '')
    + '. Not retried — a 4xx does not fix itself. '
    + (status === 401 || status === 403
        ? 'That status is almost always the token: expired, or missing w_organization_social.'
        : status === 426
          ? 'HTTP 426 is a retired LinkedIn-Version. Raise LINKEDIN_VERSION in config.'
          : '');
} else {
  outcome = 'UNKNOWN';
  reason = 'no URN and no error came back (HTTP ' + status + '). The post may or may not '
    + 'have gone up. LOOK AT THE PAGE before running this again — this is the one case '
    + 'where a retry can double-post.';
}

return [{
  json: Object.assign({}, draft, {
    _outcome: outcome,
    _urn: urn,
    _status: status,
    _posted: outcome === 'POSTED',
    _reason: reason,
    _post_url: urn ? 'https://www.linkedin.com/feed/update/' + urn + '/' : ''
  })
}];

// The publish did not succeed, and it is not being retried.
//
// FAILED means a 4xx with a reason — read it, fix the cause, run again.
// DUPLICATE means it is already on the page. Stop.
// UNKNOWN means look at the page with your own eyes before doing anything at all, because
// this is the one state where running again can double-post.
//
// There is no automatic retry anywhere in this branch, on purpose.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'publish failed',
    _mode: cfg.mode,
    _reason: '[' + s._outcome + '] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// Mark the bank row published so it can never be drafted a second time.
//
// Only ever runs on a real POSTED outcome. The log already prevents a re-draft on its own —
// `_posted_slugs` is read from it — so this is the second of two independent guards, not the
// only one. Two guards because the failure it prevents is publishing the same post twice.

const cfg = $('config').first().json;
const B = cfg.bank_columns;
const d = $json;

const row = {};
row[B.slug] = d._slug;
row[B.state] = 'posted';

return [{ json: Object.assign(row, {
  _reason: 'bank row ' + d._slug + ' marked posted'
}) }];

// The row that closes the day.
//
// One row per outcome, appended — the log is never rewritten in place. `posted` is what
// silences tomorrow's duplicate check; `cancelled` is what lets workflow 01 draft again the
// same day; `expired` closes a draft nobody answered without claiming it went out.
//
// The bank row's State is updated separately, and only on a real publish. A cancelled post
// stays `ready` on purpose: cancelling means "not this one, now", not "never".

const cfg = $('config').first().json;
const L = cfg.log_columns;
const d = $json;

const status = d._outcome === 'POSTED' ? 'posted'
  : d._decision === 'cancel' ? 'cancelled'
  : d._expired ? 'expired'
  : d._outcome === 'DUPLICATE' ? 'posted'
  : 'failed';

const row = {};
row[L.date] = d._date || '';
row[L.slug] = d._slug || '';
row[L.slot] = d._slot || '';
row[L.status] = status;
row[L.channel_id] = d._channel_id || cfg.channel_id;
row[L.message_id] = d._message_id || '';
row[L.caption_fp] = d._caption_fp_now || d._caption_fp || '';
row[L.urn] = d._urn || '';
row[L.note] = [
  d._approver ? 'by ' + d._approver : '',
  d._said ? '"' + d._said + '"' : '',
  d._reason || ''
].filter(Boolean).join(' — ').slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: Object.assign(row, { _status: status, _reason: d._reason }) }];

// One line per run, for the optional Slack webhook.
//
// Every path through both workflows arrives here, including the ones that did nothing. A
// summary that only fires on success is a summary that goes quiet exactly when something is
// wrong, which is the failure mode this exists to catch: the job silently stopped drafting
// three weeks ago and nobody noticed because nothing was ever broken enough to alert.
//
// The caption is NOT included. It goes to the approval channel and nowhere else — a draft
// that reaches a second audience before it is approved has left the approval gate behind.

const cfg = $('config').first().json;
const s = $json;

const stopped = s._stopped || '';
const outcome = s._outcome || '';

const icon = outcome === 'POSTED' ? ':white_check_mark:'
  : outcome === 'FAILED' || outcome === 'UNKNOWN' || stopped === 'no image' ? ':x:'
  : stopped === 'still awaiting approval' || stopped === 'nothing awaiting' ? ':hourglass:'
  : ':information_source:';

const headline = outcome === 'POSTED'
  ? 'Published: ' + (s._slug || 'unknown')
  : stopped
    ? 'No post: ' + stopped
    : 'Draft delivered for approval: ' + (s.slug || s._slug || 'unknown');

const lines = [
  icon + ' *LinkedIn daily* — ' + headline,
  '*Mode:* ' + cfg.mode + (cfg.forced_preview ? ' (forced — demo bank in use)' : ''),
  s._reason ? '*Why:* ' + s._reason : '',
  s._post_url ? '*Post:* ' + s._post_url : '',
  s._approver ? '*Approved by:* ' + s._approver : '',
  (s._warnings && s._warnings.length) ? '*Warnings:* ' + s._warnings.join('; ') : ''
].filter(Boolean);

const text = lines.join('\n');

return [{
  json: {
    _summary: text,
    _slack_body: { text: text },
    _notify: cfg.report_enabled,
    _outcome: outcome || stopped || 'delivered',
    _reason: s._reason || ''
  }
}];
